532	+
533	+/** The outcome of one item's multi-model review. */
534	+export function summarizeVoices(result: OutcomeInput): VoiceOutcome {
535	+  const completedLabels = result.modelResults
536	+    .filter((r) => r.response !== undefined && r.error === undefined)
