542	+  for (const label of plannedLabels) {
543	+    const i = remaining.indexOf(label);
544	+    if (i >= 0) remaining.splice(i, 1);
545	+    else incomplete.push(label);
546	+  }
547	+  const band = computeVerdictBand(result.modelResults.map((r) => ({ verdictQuality: r.response?.verdictQuality })));
548	+  const completed = completedLabels.length;
549	+  const planned = plannedLabels.length;
