adversarial-review-locality.bats:178:@test "LOC-6 a primary chain with no local hop is refused before any call; an unknown locality value is refused by name" {
adversarial-review-locality.bats:194:@test "LOC-7 a local entry whose fallback_chain reaches a hosted model is hosted (cheval would walk it inside the call)" {
adversarial-review-locality.bats:210:@test "LOC-8 the multi-model reference says the Claude Code session model is exempt and remains the platform" {
